        self.assertEqual(roman_to_int('I'), 1)

    def test_upper_boundary(self):
        self.assertEqual(roman_to_int('MMMCMXCIX'), 3999)

    def test_each_subtractive_pair(self):
        for numeral, expected in [('IV', 4), ('IX', 9), ('XL', 40),
                                  ('XC', 90), ('CD', 400), ('CM', 900)]:
            with self.subTest(numeral=numeral):
                self.assertEqual(roman_to_int(numeral), expected)

    def test_large_additive_numeral(self):
        self.assertEqual(roman_to_int('MMMDCCCLXXXVIII'), 3888)


if __name__ == '__main__':
    unittest.main()
